132		 * capability that reads them resolves package subpaths against an exports map.
133		 */
134		styleSheets?: readonly WorkspaceFile[];
135		/**
136		 * The published surface of packages whose stylesheet subpaths the application
137		 * imports, as read from the installed closure. A package not read here has its
138		 * style imports left exactly as they are.
139		 */
140		packageExports?: readonly PackageExportsReading[];
141		/**
142		 * The installed dependency closure, reduced to declarations and shipped
143		 * imports. Supplying it is what lets undeclared runtime dependencies be
144		 * detected; a tree that supplies none has none detected, which is a different
145		 * thing from having none.
146		 */
147		installedPackages?: readonly InstalledPackage[];
148		/** How the workspace resolves module specifiers written in its own source. */
149		moduleResolution?: ModuleResolution;
150		/**
151		 * `TS2314` as the target line's compiler reported it, per application module.
152		 * A generic base class the application extends bare cannot be parameterised
153		 * from the source alone — the argument is a fact about the installed
154		 * declaration, and which clause is wrong is a fact the compiler states — so
155		 * this capability is reachable only for a caller that has compiled the tree. A
156		 * tree that supplies no diagnostics has no `extends` clause parameterised,
157		 * which is a different thing from having none to parameterise.
158		 */
159		baseClassDiagnostics?: readonly BaseClassDiagnosticReading[];
160		/**
161		 * The generic base classes the application extends, read from the installed
162		 * closure. Supplied beside {@link baseClassDiagnostics}: a diagnostic names the
163		 * clause and this names what the declaration publishes, and the capability
164		 * refuses every site it cannot prove from both.
165		 */
166		genericBaseClasses?: readonly GenericBaseClassReading[];
167		/**
168		 * `TS2339` as the target line's compiler reported it, per application module.
169		 * A member the current `lib.dom.d.ts` no longer declares is not readable from
170		 * the source — the source is exactly what it always was — so the seam is the
171		 * same supply-gated one {@link baseClassDiagnostics} uses. A tree that supplies
172		 * none has none accommodated.
173		 */
174		missingMemberDiagnostics?: readonly MissingMemberDiagnosticReading[];
175		/**
176		 * What packages whose subpaths the application imports actually publish, read
177		 * from the installed closure. A package not read here has its deep imports left
178		 * exactly as they are: whether a subpath is reachable is a fact about the
179		 * installed package's `exports` map, and nothing in the source states it.
180		 */
181		deepImportReadings?: readonly DeepImportReading[];
182		/**
183		 * The `@types/` packages the *era* closure carried, by name. A package this
184		 * application imports directly and the era manifest never declared may have had
185		 * its type declarations supplied the same accidental way its runtime was; this
186		 * reading is what lets that companion be declared beside it rather than
187		 * inferred from a name.
188		 */
189		eraClosureTypePackages?: readonly string[];
190	}>;
191	
192	/**
193	 * The `TS2339` diagnostics one application module carries, keyed by the path the
194	 * workspace writes for it — the compiler's own 1-based positions into the bytes
195	 * the caller compiled.
196	 */
197	export type MissingMemberDiagnosticReading = Readonly<{
198		path: string;
199		diagnostics: readonly MissingMemberDiagnostic[];
200	}>;
201	
202	/**
203	 * The `TS2314` diagnostics one application module carries, keyed by the path the
204	 * workspace writes for it. `line` and `column` are the compiler's own 1-based
205	 * pair, and they are positions in the bytes the caller compiled: the capability
206	 * checks that the name it was told to fill is written where it was told, and
207	 * refuses by name rather than editing when it is not.
208	 */
209	export type BaseClassDiagnosticReading = Readonly<{
210		path: string;
211		diagnostics: readonly UnparameterisedBaseClassDiagnostic[];
212	}>;
213	
214	export type MigratedFile = Readonly<{
215		path: string;
216		kind: 'application' | 'workspace';
217		changed: boolean;
218		sha256Before: string;
219		sha256After: string;
220		source: string;
221		changes: readonly string[];
222	}>;
223	
224	export type AngularMigration = Readonly<{
225		cell: string;
226		files: readonly MigratedFile[];
227		applicationFilesChanged: number;
228		workspaceFilesChanged: number;
229		applicationFilesScanned: number;
230		unhandled: readonly string[];
231		/**
232		 * Capabilities the migrated workspace deliberately no longer has, one line
233		 * per removal — a dropped lint target, a dropped configuration file, a
234		 * package the cell read and found no successor for. A reader is owed these by
235		 * name: they are the difference between the era workspace and this one that a
236		 * clean changeset would otherwise hide.
237		 */
238		declaredDifferences: readonly string[];
239		/** Files the migration decided the tree should no longer carry. */
240		removedFiles: readonly string[];
241	}>;
242	
243	function sha256(value: string): string {
244		return createHash('sha256').update(value).digest('hex');
245	}
246	
247	/**
248	 * Parse a workspace document only far enough to decide which format it is in.
249	 *
250	 * A document that is not JSON at all is handed on unparsed: the migration that
251	 * reads it next refuses it with the diagnosable error it already writes, and
252	 * duplicating that refusal here would report the same defect twice under two
253	 * different names.
254	 */
255	function safeParseJson(source: string): unknown {
256		try {
257			return JSON.parse(source) as unknown;
258		} catch {
259			return null;
260		}
261	}
262	
263	function describeConfigChange(change: ConfigChange): string {
264		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
265		if (change.from === null) return `added ${change.path} = ${change.to}`;
266		return `${change.path}: ${change.from} -> ${change.to}`;
267	}
268	
269	function describeDependencyChange(change: DependencyChange): string {
270		const target = `${change.field}.${change.name}`;
271		return change.to === null
272			? `removed ${target} (was ${change.from}) — ${change.reason}`
273			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
274	}
275	
276	function describeSourceChange(
277		change:
278			| SourceChange
279			| NgrxEffectChange
280			| SentryV8Change
281			| ModalContentParamsChange
282			| StyleImportChange,
283	): string {
284		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
285	}
286	
287	/**
288	 * An entry-components removal names no successor, because the property has
289	 * none: what a reader needs from it is which components the dropped list named,
290	 * so the proof that each is still reached can be checked against the literal.
291	 */
292	function describeEntryComponentsChange(change: EntryComponentsChange): string {
293		return `line ${change.line}: ${change.kind} of ${change.symbols.join(', ')}`;
294	}
295	
296	/**
297	 * A type-position insertion names no predecessor, because there was none: what a
298	 * reader needs is the argument that was written and where the capability read it,
299	 * so the claim can be checked against the same two places the source states it.
300	 */
301	function describeModuleWithProvidersChange(change: ModuleWithProvidersChange): string {
302		return `line ${change.line}: ${change.kind} <${change.argument}> read from ${change.readFrom}`;
303	}
304	
305	/**
306	 * `void` is a claim about every value a subject or a promise will ever carry, and
307	 * the evidence for it is the count of zero-argument settlements the capability
308	 * read. The count is reported so the claim can be checked against the binding.
309	 */
310	function describeVoidSubjectChange(change: VoidSubjectChange): string {
311		return (
312			`line ${change.line}: ${change.kind} <void> on ${change.binding}, proved by ` +
313			`${String(change.callSites)} zero-argument next call(s)`
314		);
315	}
316	
317	function describeVoidExecutorChange(change: VoidExecutorChange): string {
318		return (
319			`line ${change.line}: ${change.kind} <void>, proved by ${String(change.callSites)} ` +
320			`zero-argument ${change.parameter} call(s)`
321		);
322	}
323	
324	/**
325	 * A base-class parameterisation carries two facts a reader is owed beyond the
326	 * argument: the package the argument was imported from, and whether importing it
327	 * meant a new declaration in the module.
328	 */
329	function describeBaseClassChange(change: BaseClassParameterisationChange): string {
330		return (
331			`line ${change.line}: ${change.kind} ${change.base}<${change.argument}> from ` +
332			`${change.specifier} (${change.importAdded ? 'import added' : 'existing import extended'})`
333		);
334	}
335	
336	/**
337	 * A synthesized decorator names no predecessor, because there was none. What a
338	 * reader needs is which Angular features the class used — the whole of the
339	 * evidence that it needed a decorator at all — so the claim can be checked
340	 * against the class the compiler will now compile.
341	 */
342	function describeUndecoratedBaseClassChange(change: UndecoratedBaseClassChange): string {
343		return (
344			`line ${change.line}: ${change.kind} ${change.decorator} on ${change.className}, which uses ` +
345			`${change.features.join(', ')} (${change.importAdded ? 'import added' : 'existing import extended'})`
346		);
347	}
348	
349	/**
350	 * A widened receiver names the type the compiler resolved and the type it was
351	 * widened to, so the claim can be checked against the declaration that stopped
352	 * carrying the member.
353	 */
354	function describeDepartedDomMemberChange(change: DepartedDomMemberChange): string {
355		return (
356			`line ${change.line}: ${change.kind} ${change.receiver}.${change.member} — ` +
357			`${change.declaredType} no longer declares it, receiver widened to ${change.widenedTo}`
358		);
359	}
360	
361	function describeDeepImportChange(change: DeepImportChange): string {
362		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to} (${change.symbols.join(', ')})`;
363	}
364	
365	function describeBindingReorderChange(change: BindingReorderChange): string {
366		return (
367			`line ${change.line}: ${change.kind} on <${change.element}> (${change.directive}) — ` +
368			`${change.before.join(', ')} -> ${change.after.join(', ')}, forced by ${change.edges.join('; ')}`
369		);
370	}
371	
372	function file(
373		input: WorkspaceFile,
374		source: string,
375		kind: MigratedFile['kind'],
376		changes: readonly string[],
377	): MigratedFile {
378		return Object.freeze({
379			path: input.path,
380			kind,
381			changed: source !== input.source,
382			sha256Before: sha256(input.source),
383			sha256After: sha256(source),
384			source,
385			changes: Object.freeze([...changes]),
386		});
387	}
388	
389	/**
390	 * Apply every capability of the adapter to one workspace.
391	 *
392	 * Order matters in three places, and each is named where it happens: the
393	 * workspace migration decides which builder targets cannot be carried, and the
394	 * packages those targets released are what the manifest alignment then removes;
395	 * `entryComponents` is dropped after the capabilities that rewrite the literal it
396	 * reads; and the one capability positioned by compiler coordinates runs before
397	 * the capabilities that move them. Nothing else is ordered, and no capability
398	 * reads a file it was not handed.
399	 */
400	export function migrateAngularCliEraWorkspace(
401		input: AngularMigrationInput,
402		cell: AngularTargetCell,
403	): AngularMigration {
404		const unhandled: string[] = [];
405		const declaredDifferences: string[] = [];
406		const fragments: Record<string, string> = {};
407		for (const fragment of input.webpackFragments ?? [])
408			fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
409		/**
410		 * A workspace in the pre-`angular.json` Angular CLI 1.x format is translated
411		 * into the modern one before anything else reads it. Every capability below
412		 * expects a `projects` map with `architect` targets, and the era document has
413		 * neither; synthesizing first is what lets the rest of the adapter run on a
414		 * CLI 1.x tree without one of them learning a second workspace format.
415		 */
416		let synthesis: SynthesizedWorkspace | null = null;
417		let workspaceConfigSource = input.workspaceConfig.source;
418		if (isAngularCliOneWorkspace(safeParseJson(input.workspaceConfig.source))) {
419			synthesis = synthesizeAngularWorkspace(
420				input.workspaceConfig.source,
421				cell,
422				input.workspaceConfig.path,
423			);
424			workspaceConfigSource = synthesis.config;
425			unhandled.push(...synthesis.unhandled);
426			declaredDifferences.push(...synthesis.declaredDifferences);
427		}
428		const workspace = migrateAngularWorkspace(workspaceConfigSource, cell, fragments);
429		unhandled.push(...workspace.unhandled);
430		declaredDifferences.push(...workspace.declaredDifferences);
431		const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
432		declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
433		for (const absorbed of workspace.absorbedFragments)
434			unhandled.push(
435				`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
436					`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
437					absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
438			);
439		const manifest: unknown = JSON.parse(input.packageManifest.source);
440		if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
441			throw new Error('Angular migration: the package manifest is not a JSON object');
442		const aligned = alignAngularPackageManifest(
443			manifest as Readonly<Record<string, unknown>>,
444			cell,
445			workspace.removedPackages,
446		);
447		unhandled.push(...aligned.unhandled);
448		declaredDifferences.push(...aligned.declaredDifferences);
449		/**
450		 * Holes the closure carries are closed after the cell alignment, not before:
451		 * the cell decides which lines the workspace runs, and an undeclared edge is
452		 * declared at the line the cell read for it.
453		 */
454		const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
455		const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
456		unhandled.push(...declared.unhandled);
457		declaredDifferences.push(...declared.declaredDifferences);
458		/**
459		 * The holes the *application's own source* carries are closed after the cell
460		 * alignment for a second reason: the alignment is what drops the packages the
461		 * cell found no successor for, and a package the application imports directly
462		 * that the era closure supplied through one of those is only visible as a hole
463		 * once the wrapper is gone. Reading it before the disposition would report the
464		 * edge as satisfied and leave the migrated tree unable to resolve it.
465		 */
466		const applicationDependencies = declareApplicationSourceDependencies(
467			declared.manifest,
468			readApplicationPackageUses(input.sourceModules),
469			cell,
470			input.eraClosureTypePackages ?? [],
471		);
472		unhandled.push(...applicationDependencies.unhandled);
473		declaredDifferences.push(...applicationDependencies.declaredDifferences);
474		/**
475		 * The packages the migrated workspace's own targets name are declared last,
476		 * after every capability that decides which targets survive: a builder
477		 * declaration for a target the workspace migration removed would install a
478		 * toolchain nothing runs.
479		 */
480		const builders = declareBuilderPackages(
481			applicationDependencies.manifest,
482			workspace.config,
483			cell,
484		);
485		unhandled.push(...builders.unhandled);
486		/**
487		 * The workspace's own runtime declaration is retargeted after every
488		 * capability that decides what the closure is: `engines.node` is a statement
489		 * about the cell the manifest now installs for, so it is written once the
490		 * manifest has finished becoming that cell's manifest. It stands down on a
491		 * workspace that declares no engines, and on one whose declaration already
492		 * admits the cell's Node line.
493		 */
494		const engines = retargetWorkspaceEngines(builders.manifest, cell);
495		unhandled.push(...engines.unhandled);
496		declaredDifferences.push(...engines.declaredDifferences);
497		const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
498		unhandled.push(...tsConfig.unhandled);
499		const files: MigratedFile[] = [
500			file(
501				input.packageManifest,
502				`${JSON.stringify(engines.manifest, null, 2)}\n`,
503				'workspace',
504				[
505					...aligned.changes.map(describeDependencyChange),
506					...declared.declarations.map(
507						(entry) =>
508							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
509					),
510					...applicationDependencies.declarations.map(
511						(entry) =>
512							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
513					),
514					...builders.declarations.map(
515						(entry) =>
516							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
517					),
518					...(engines.retarget === null
519						? []
520						: [
521								`retargeted ${engines.retarget.field} from ${engines.retarget.from} to ` +
522									`${engines.retarget.to} — ${engines.retarget.reason}`,
523							]),
524				],
525			),
526			file(
527				synthesis === null
528					? input.workspaceConfig
529					: { path: synthesis.path, source: input.workspaceConfig.source },
530				workspace.config,
531				'workspace',
532				synthesis === null
533					? workspace.changes.map(describeConfigChange)
534					: [
535							`synthesized ${synthesis.path} from ${synthesis.replacedPath}, the pre-angular.json ` +
536								'Angular CLI 1.x workspace format; the digest recorded before is that file',
537							...synthesis.changes.map(describeConfigChange),
538							...workspace.changes.map(describeConfigChange),
539						],
540			),
541			file(
542				input.tsConfig,
543				tsConfig.config,
544				'workspace',
545				tsConfig.changes.map(describeConfigChange),
546			),
547		];
548		/**
549		 * Source capabilities run in sequence over each module, each one handed what
550		 * the last produced. They are independent — one rewrites module specifiers,
551		 * the next replaces a removed NgRx decorator — and a module is counted as
552		 * changed if any of them changed a byte of it.
553		 */
554		/**
555		 * One capability is not per-module and cannot be: rewriting a modal call site
556		 * without rewriting the content component it supplied is the silent failure
557		 * that capability exists to refuse. It runs over the whole tree first, and
558		 * what it produced is what the per-module capabilities then see.
559		 */
560		const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
561		unhandled.push(...modal.unhandled);
562		const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
563		const baseClassDiagnostics = new Map(
564			(input.baseClassDiagnostics ?? []).map((entry) => [entry.path, entry.diagnostics]),
565		);
566		const missingMembers = new Map(
567			(input.missingMemberDiagnostics ?? []).map((entry) => [entry.path, entry.diagnostics]),
568		);
569		for (const module of [...input.sourceModules].sort((left, right) =>
570			compareStrings(left.path, right.path),
571		)) {
572			const modalFile = modalByPath.get(module.path);
573			const entrySource = modalFile?.source ?? module.source;
574			/**
575			 * The compiler-positioned capability runs first of the per-module
576			 * capabilities, because its input is a pair of coordinates into bytes the
577			 * caller compiled and every capability that edits the module moves them. It
578			 * is safe wherever it is placed — it refuses a position where the name it was
579			 * told to fill is not written — but placed first it is refused least often
580			 * for a reason that is about ordering rather than about the application.
581			 */
582			const baseClasses = parameteriseBaseClasses(
583				module.path,
584				entrySource,
585				baseClassDiagnostics.get(module.path) ?? [],
586				input.genericBaseClasses ?? [],
587			);
588			/**
589			 * The second compiler-positioned capability runs beside the first and for
590			 * the same reason: a `TS2339` position is a position in the bytes the caller
591			 * compiled, and the base-class parameterisation above only ever writes inside
592			 * an `extends` clause's type arguments — so a position it moved is a position
593			 * on the same line, and this capability re-checks the member is written where
594			 * it was told before it edits anything.
595			 */
596			const departedDomMembers = accommodateDepartedDomMembers(
597				module.path,
598				baseClasses.source,
599				missingMembers.get(module.path) ?? [],
600			);
601			const migrated = migrateAngularSourceModule(module.path, departedDomMembers.source);
602			const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
603			const sentry = migrateSentryV8Tracing(module.path, effects.source);
604			/**
605			 * Deep imports are redirected after the specifier rewrites and before the
606			 * capabilities that read module literals: an unreachable subpath is a
607			 * question about the specifier, and the answer changes which declaration each
608			 * symbol arrives on. Every reading the caller supplied is offered the module
609			 * in turn, because two packages are two exports maps.
610			 */
611			let deepImportSource = sentry.source;
612			const deepImportChanges: DeepImportChange[] = [];
613			for (const reading of input.deepImportReadings ?? []) {
614				const redirected = redirectUnreachableImports(module.path, deepImportSource, reading);
615				unhandled.push(...redirected.unhandled);
616				deepImportChanges.push(...redirected.changes);
617				deepImportSource = redirected.source;
618			}
619			/**
620			 * `entryComponents` is dropped last of the per-module capabilities, and the
621			 * order is not arbitrary: the capability proves, per literal, that every
622			 * component the property names is still reached by `declarations` or
623			 * `bootstrap` of the same literal, and it should see the literal as the
624			 * capabilities before it left it rather than as the era file wrote it.
625			 */
626			const entryComponents = removeEntryComponents(module.path, deepImportSource);
627			/**
628			 * Three type-position insertions close the sequence. Each one is a claim
629			 * about a type the source itself already states — the module a static factory
630			 * is declared on, and the `void` a subject or a promise executor proves by
631			 * settling with nothing — so each gates on its own construct and inserts
632			 * nothing where it cannot read one. They are placed after the specifier
633			 * rewrites because the bindings they resolve are the bindings those rewrites
634			 * left, and before nothing: no later capability reads a module.
635			 */
636			const moduleWithProviders = addModuleWithProvidersTypeArgument(
637				module.path,
638				entryComponents.source,
639			);
640			const voidSubjects = parameteriseVoidSubjects(module.path, moduleWithProviders.source);
641			const voidExecutors = parameteriseVoidPromiseExecutors(module.path, voidSubjects.source);
642			/**
643			 * The decorator synthesis closes the sequence. It inserts a line above a class
644			 * declaration and a name into an import declaration, which moves every offset
645			 * below both — so it runs after every capability positioned by an offset, and
646			 * it reads its own precondition out of the module the others left.
647			 */
648			const undecorated = decorateUndecoratedBaseClasses(
649				module.path,
650				voidExecutors.source,
651				cell,
652			);
653			unhandled.push(
654				...departedDomMembers.unhandled,
655				...undecorated.unhandled,
656				...baseClasses.unhandled,
657				...migrated.unhandled,
658				...effects.unhandled,
659				...sentry.unhandled,
660				...entryComponents.unhandled,
661				...moduleWithProviders.unhandled,
662				...voidSubjects.unhandled,
663				...voidExecutors.unhandled,
664			);
665			files.push(
666				file(module, undecorated.source, 'application', [
667					...(modalFile?.changes ?? []).map(describeSourceChange),
668					...baseClasses.changes.map(describeBaseClassChange),
669					...departedDomMembers.changes.map(describeDepartedDomMemberChange),
670					...deepImportChanges.map(describeDeepImportChange),
671					...undecorated.changes.map(describeUndecoratedBaseClassChange),
672					...migrated.changes.map(describeSourceChange),
673					...effects.changes.map(describeSourceChange),
674					...sentry.changes.map(describeSourceChange),
675					...entryComponents.changes.map(describeEntryComponentsChange),
676					...moduleWithProviders.changes.map(describeModuleWithProvidersChange),
677					...voidSubjects.changes.map(describeVoidSubjectChange),
678					...voidExecutors.changes.map(describeVoidExecutorChange),
679				]),
680			);
681		}
682		/**
683		 * Templates are the last application capability, and it is cross-file by
684		 * nature: whether a call site's binding order is safe is a question about the
685		 * directive the element resolves to, read from that directive's own class.
686		 * The readings are taken from the modules as the per-module capabilities left
687		 * them, so a directive whose imports those capabilities rewrote still
688		 * resolves. A template no directive reading touches is carried through
689		 * unchanged and still counted, so the scanned total means what it says.
690		 */
691		const directiveReadings: DirectiveBindingReading[] = [];
692		for (const entry of files)
693			if (entry.kind === 'application' && entry.path.endsWith('.ts'))
694				directiveReadings.push(...readDirectiveBindingDependencies(entry.path, entry.source));
695		for (const template of [...(input.templates ?? [])].sort((left, right) =>
696			compareStrings(left.path, right.path),
697		)) {
698			const reordered = reorderTemplateBindings(template.path, template.source, directiveReadings);
699			unhandled.push(...reordered.unhandled);
700			files.push(
701				file(
702					template,
703					reordered.source,
704					'application',
705					reordered.changes.map(describeBindingReorderChange),
706				),
707			);
708		}
709		/**
710		 * Stylesheets are application files too, and a blocked package subpath is an
711		 * application file that no longer builds. Each is offered to every package
712		 * reading the caller supplied; a stylesheet no reading touches is carried
713		 * through unchanged and still counted, so the scanned total means what it says.
714		 */
715		for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
716			compareStrings(left.path, right.path),
717		)) {
718			let source = sheet.source;
719			const changes: string[] = [];
720			for (const reading of input.packageExports ?? []) {
721				const styles = migratePackageStyleImports(sheet.path, source, reading);
722				unhandled.push(...styles.unhandled);
723				declaredDifferences.push(...styles.declaredDifferences);
724				changes.push(...styles.changes.map(describeSourceChange));
725				source = styles.source;
726			}
727			files.push(file(sheet, source, 'application', changes));
728		}
729		const applicationFiles = files.filter((entry) => entry.kind === 'application');
730		return Object.freeze({
731			cell: cell.id,
732			files: Object.freeze(files),
733			applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
734			workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
735				.length,
736			applicationFilesScanned: applicationFiles.length,
737			unhandled: Object.freeze([...new Set(unhandled)]),
738			declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
739			removedFiles: Object.freeze([
740				...configRemovals.map((removal) => removal.at),
741				...(synthesis === null ? [] : [synthesis.replacedPath]),
742			]),
743		});
744	}
745

file.content:
/**
 * The composed Angular CLI era migration: workspace configuration, TypeScript
 * configuration, package manifest and application source, lifted onto one
 * declared target cell and reported as a single itemised changeset.
 *
 * The changeset is the product. It records, per file, the bytes before and
 * after as digests and the individual changes that produced them, and it
 * separates application files from workspace files so that a count of changed
 * application files means what it says: source the application owns, changed by
 * a transform, not a version number edited in a manifest.
 */

import { createHash } from 'node:crypto';
import {
	alignAngularPackageManifest,
	compareStrings,
	type AngularTargetCell,
	type DependencyChange,
} from './angular-target-cell.ts';
import { migrateAngularSourceModule, type SourceChange } from './angular-source-migration.ts';
import {
	migrateModalContentParams,
	type ModalContentParamsChange,
	type ModuleResolution,
} from './modal-content-params-migration.ts';
import { migrateNgrxEffectDecorators, type NgrxEffectChange } from './ngrx-effects-migration.ts';
import {
	migratePackageStyleImports,
	type PackageExportsReading,
	type StyleImportChange,
} from './package-exports-style-imports.ts';
import { migrateSentryV8Tracing, type SentryV8Change } from './sentry-v8-migration.ts';
import {
	removeEntryComponents,
	type EntryComponentsChange,
} from './entry-components-removal.ts';
import {
	readDirectiveBindingDependencies,
	reorderTemplateBindings,
	type BindingReorderChange,
	type DirectiveBindingReading,
} from './template-binding-reorder.ts';
import {
	declareUndeclaredRuntimeDependencies,
	undeclaredRuntimeDependencies,
	type InstalledPackage,
} from './undeclared-runtime-dependency.ts';
import {
	migrateAngularTsConfig,
	migrateAngularWorkspace,
	normalizeFragmentPath,
	type ConfigChange,
} from './angular-workspace-migration.ts';
import {
	isAngularCliOneWorkspace,
	synthesizeAngularWorkspace,
	type SynthesizedWorkspace,
} from './angular-cli-json-workspace-synthesis.ts';
import { tslintConfigRemovals } from './tslint-toolchain-removal.ts';
import { declareBuilderPackages } from './builder-package-declaration.ts';
import { retargetWorkspaceEngines } from './workspace-engines-retarget.ts';
import {
	addModuleWithProvidersTypeArgument,
	type ModuleWithProvidersChange,
} from './module-with-providers-type-argument.ts';
import {
	parameteriseVoidSubjects,
	type VoidSubjectChange,
} from './subject-void-type-argument.ts';
import {
	parameteriseVoidPromiseExecutors,
	type VoidExecutorChange,
} from './promise-executor-void-parameter.ts';
import {
	parameteriseBaseClasses,
	type BaseClassParameterisationChange,
	type GenericBaseClassReading,
	type UnparameterisedBaseClassDiagnostic,
} from './unparameterised-base-class.ts';
import {
	decorateUndecoratedBaseClasses,
	type UndecoratedBaseClassChange,
} from './undecorated-angular-base-class.ts';
import {
	accommodateDepartedDomMembers,
	type DepartedDomMemberChange,
} from './departed-dom-lib-member.ts';
import { type MissingMemberDiagnostic } from './declared-type-member-rename.ts';
import {
	declareApplicationSourceDependencies,
	readApplicationPackageUses,
} from './application-source-dependency.ts';
import {
	redirectUnreachableImports,
	type DeepImportChange,
	type DeepImportReading,
} from './deep-import-redirection.ts';

export type WorkspaceFile = Readonly<{ path: string; source: string }>;

export type AngularMigrationInput = Readonly<{
	packageManifest: WorkspaceFile;
	workspaceConfig: WorkspaceFile;
	tsConfig: WorkspaceFile;
	/** Application source modules, as read from the workspace. */
	sourceModules: readonly WorkspaceFile[];
	/**
	 * Component templates the application owns, kept apart from
	 * {@link sourceModules} because they are not modules: no source transform
	 * parses them, and the only capability that reads them reorders directive
	 * bindings a component class proves are order-dependent. A tree that supplies
	 * none has none reordered, which is a different thing from having none to
	 * reorder.
	 */
	templates?: readonly WorkspaceFile[];
	/**
	 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
	 * writes for them. A fragment a target references but that is not supplied
	 * here is reported unread and its wrapper builder is left in place.
	 */
	webpackFragments?: readonly WorkspaceFile[];
	/**
	 * Every workspace-relative path the tree carries, for capabilities that
	 * decide a file should no longer exist. Only paths are needed: a file removed
	 * because the toolchain that read it is gone does not have to be parsed. A
	 * tree that supplies no list has no files removed.
	 */
	workspaceFiles?: readonly string[];
	/**
	 * Stylesheets the application owns, kept apart from {@link sourceModules}
	 * because they are not modules: no source transform parses them, and the only
	 * capability that reads them resolves package subpaths against an exports map.
	 */
	styleSheets?: readonly WorkspaceFile[];
	/**
	 * The published surface of packages whose stylesheet subpaths the application
	 * imports, as read from the installed closure. A package not read here has its
	 * style imports left exactly as they are.
	 */
	packageExports?: readonly PackageExportsReading[];
	/**
	 * The installed dependency closure, reduced to declarations and shipped
	 * imports. Supplying it is what lets undeclared runtime dependencies be
	 * detected; a tree that supplies none has none detected, which is a different
	 * thing from having none.
	 */
	installedPackages?: readonly InstalledPackage[];
	/** How the workspace resolves module specifiers written in its own source. */
	moduleResolution?: ModuleResolution;
	/**
	 * `TS2314` as the target line's compiler reported it, per application module.
	 * A generic base class the application extends bare cannot be parameterised
	 * from the source alone — the argument is a fact about the installed
	 * declaration, and which clause is wrong is a fact the compiler states — so
	 * this capability is reachable only for a caller that has compiled the tree. A
	 * tree that supplies no diagnostics has no `extends` clause parameterised,
	 * which is a different thing from having none to parameterise.
	 */
	baseClassDiagnostics?: readonly BaseClassDiagnosticReading[];
	/**
	 * The generic base classes the application extends, read from the installed
	 * closure. Supplied beside {@link baseClassDiagnostics}: a diagnostic names the
	 * clause and this names what the declaration publishes, and the capability
	 * refuses every site it cannot prove from both.
	 */
	genericBaseClasses?: readonly GenericBaseClassReading[];
	/**
	 * `TS2339` as the target line's compiler reported it, per application module.
	 * A member the current `lib.dom.d.ts` no longer declares is not readable from
	 * the source — the source is exactly what it always was — so the seam is the
	 * same supply-gated one {@link baseClassDiagnostics} uses. A tree that supplies
	 * none has none accommodated.
	 */
	missingMemberDiagnostics?: readonly MissingMemberDiagnosticReading[];
	/**
	 * What packages whose subpaths the application imports actually publish, read
	 * from the installed closure. A package not read here has its deep imports left
	 * exactly as they are: whether a subpath is reachable is a fact about the
	 * installed package's `exports` map, and nothing in the source states it.
	 */
	deepImportReadings?: readonly DeepImportReading[];
	/**
	 * The `@types/` packages the *era* closure carried, by name. A package this
	 * application imports directly and the era manifest never declared may have had
	 * its type declarations supplied the same accidental way its runtime was; this
	 * reading is what lets that companion be declared beside it rather than
	 * inferred from a name.
	 */
	eraClosureTypePackages?: readonly string[];
}>;

/**
 * The `TS2339` diagnostics one application module carries, keyed by the path the
 * workspace writes for it — the compiler's own 1-based positions into the bytes
 * the caller compiled.
 */
export type MissingMemberDiagnosticReading = Readonly<{
	path: string;
	diagnostics: readonly MissingMemberDiagnostic[];
}>;

/**
 * The `TS2314` diagnostics one application module carries, keyed by the path the
 * workspace writes for it. `line` and `column` are the compiler's own 1-based
 * pair, and they are positions in the bytes the caller compiled: the capability
 * checks that the name it was told to fill is written where it was told, and
 * refuses by name rather than editing when it is not.
 */
export type BaseClassDiagnosticReading = Readonly<{
	path: string;
	diagnostics: readonly UnparameterisedBaseClassDiagnostic[];
}>;

export type MigratedFile = Readonly<{
	path: string;
	kind: 'application' | 'workspace';
	changed: boolean;
	sha256Before: string;
	sha256After: string;
	source: string;
	changes: readonly string[];
}>;

export type AngularMigration = Readonly<{
	cell: string;
	files: readonly MigratedFile[];
	applicationFilesChanged: number;
	workspaceFilesChanged: number;
	applicationFilesScanned: number;
	unhandled: readonly string[];
	/**
	 * Capabilities the migrated workspace deliberately no longer has, one line
	 * per removal — a dropped lint target, a dropped configuration file, a
	 * package the cell read and found no successor for. A reader is owed these by
	 * name: they are the difference between the era workspace and this one that a
	 * clean changeset would otherwise hide.
	 */
	declaredDifferences: readonly string[];
	/** Files the migration decided the tree should no longer carry. */
	removedFiles: readonly string[];
}>;

function sha256(value: string): string {
	return createHash('sha256').update(value).digest('hex');
}

/**
 * Parse a workspace document only far enough to decide which format it is in.
 *
 * A document that is not JSON at all is handed on unparsed: the migration that
 * reads it next refuses it with the diagnosable error it already writes, and
 * duplicating that refusal here would report the same defect twice under two
 * different names.
 */
function safeParseJson(source: string): unknown {
	try {
		return JSON.parse(source) as unknown;
	} catch {
		return null;
	}
}

function describeConfigChange(change: ConfigChange): string {
	if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
	if (change.from === null) return `added ${change.path} = ${change.to}`;
	return `${change.path}: ${change.from} -> ${change.to}`;
}

function describeDependencyChange(change: DependencyChange): string {
	const target = `${change.field}.${change.name}`;
	return change.to === null
		? `removed ${target} (was ${change.from}) — ${change.reason}`
		: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
}

function describeSourceChange(
	change:
		| SourceChange
		| NgrxEffectChange
		| SentryV8Change
		| ModalContentParamsChange
		| StyleImportChange,
): string {
	return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
}

/**
 * An entry-components removal names no successor, because the property has
 * none: what a reader needs from it is which components the dropped list named,
 * so the proof that each is still reached can be checked against the literal.
 */
function describeEntryComponentsChange(change: EntryComponentsChange): string {
	return `line ${change.line}: ${change.kind} of ${change.symbols.join(', ')}`;
}

/**
 * A type-position insertion names no predecessor, because there was none: what a
 * reader needs is the argument that was written and where the capability read it,
 * so the claim can be checked against the same two places the source states it.
 */
function describeModuleWithProvidersChange(change: ModuleWithProvidersChange): string {
	return `line ${change.line}: ${change.kind} <${change.argument}> read from ${change.readFrom}`;
}

/**
 * `void` is a claim about every value a subject or a promise will ever carry, and
 * the evidence for it is the count of zero-argument settlements the capability
 * read. The count is reported so the claim can be checked against the binding.
 */
function describeVoidSubjectChange(change: VoidSubjectChange): string {
	return (
		`line ${change.line}: ${change.kind} <void> on ${change.binding}, proved by ` +
		`${String(change.callSites)} zero-argument next call(s)`
	);
}

function describeVoidExecutorChange(change: VoidExecutorChange): string {
	return (
		`line ${change.line}: ${change.kind} <void>, proved by ${String(change.callSites)} ` +
		`zero-argument ${change.parameter} call(s)`
	);
}

/**
 * A base-class parameterisation carries two facts a reader is owed beyond the
 * argument: the package the argument was imported from, and whether importing it
 * meant a new declaration in the module.
 */
function describeBaseClassChange(change: BaseClassParameterisationChange): string {
	return (
		`line ${change.line}: ${change.kind} ${change.base}<${change.argument}> from ` +
		`${change.specifier} (${change.importAdded ? 'import added' : 'existing import extended'})`
	);
}

/**
 * A synthesized decorator names no predecessor, because there was none. What a
 * reader needs is which Angular features the class used — the whole of the
 * evidence that it needed a decorator at all — so the claim can be checked
 * against the class the compiler will now compile.
 */
function describeUndecoratedBaseClassChange(change: UndecoratedBaseClassChange): string {
	return (
		`line ${change.line}: ${change.kind} ${change.decorator} on ${change.className}, which uses ` +
		`${change.features.join(', ')} (${change.importAdded ? 'import added' : 'existing import extended'})`
	);
}

/**
 * A widened receiver names the type the compiler resolved and the type it was
 * widened to, so the claim can be checked against the declaration that stopped
 * carrying the member.
 */
function describeDepartedDomMemberChange(change: DepartedDomMemberChange): string {
	return (
		`line ${change.line}: ${change.kind} ${change.receiver}.${change.member} — ` +
		`${change.declaredType} no longer declares it, receiver widened to ${change.widenedTo}`
	);
}

function describeDeepImportChange(change: DeepImportChange): string {
	return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to} (${change.symbols.join(', ')})`;
}

function describeBindingReorderChange(change: BindingReorderChange): string {
	return (
		`line ${change.line}: ${change.kind} on <${change.element}> (${change.directive}) — ` +
		`${change.before.join(', ')} -> ${change.after.join(', ')}, forced by ${change.edges.join('; ')}`
	);
}

function file(
	input: WorkspaceFile,
	source: string,
	kind: MigratedFile['kind'],
	changes: readonly string[],
): MigratedFile {
	return Object.freeze({
		path: input.path,
		kind,
		changed: source !== input.source,
		sha256Before: sha256(input.source),
		sha256After: sha256(source),
		source,
		changes: Object.freeze([...changes]),
	});
}

/**
 * Apply every capability of the adapter to one workspace.
 *
 * Order matters in three places, and each is named where it happens: the
 * workspace migration decides which builder targets cannot be carried, and the
 * packages those targets released are what the manifest alignment then removes;
 * `entryComponents` is dropped after the capabilities that rewrite the literal it
 * reads; and the one capability positioned by compiler coordinates runs before
 * the capabilities that move them. Nothing else is ordered, and no capability
 * reads a file it was not handed.
 */
export function migrateAngularCliEraWorkspace(
	input: AngularMigrationInput,
	cell: AngularTargetCell,
): AngularMigration {
	const unhandled: string[] = [];
	const declaredDifferences: string[] = [];
	const fragments: Record<string, string> = {};
	for (const fragment of input.webpackFragments ?? [])
		fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
	/**
	 * A workspace in the pre-`angular.json` Angular CLI 1.x format is translated
	 * into the modern one before anything else reads it. Every capability below
	 * expects a `projects` map with `architect` targets, and the era document has
	 * neither; synthesizing first is what lets the rest of the adapter run on a
	 * CLI 1.x tree without one of them learning a second workspace format.
	 */
	let synthesis: SynthesizedWorkspace | null = null;
	let workspaceConfigSource = input.workspaceConfig.source;
	if (isAngularCliOneWorkspace(safeParseJson(input.workspaceConfig.source))) {
		synthesis = synthesizeAngularWorkspace(
			input.workspaceConfig.source,
			cell,
			input.workspaceConfig.path,
		);
		workspaceConfigSource = synthesis.config;
		unhandled.push(...synthesis.unhandled);
		declaredDifferences.push(...synthesis.declaredDifferences);
	}
	const workspace = migrateAngularWorkspace(workspaceConfigSource, cell, fragments);
	unhandled.push(...workspace.unhandled);
	declaredDifferences.push(...workspace.declaredDifferences);
	const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
	declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
	for (const absorbed of workspace.absorbedFragments)
		unhandled.push(
			`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
				`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
				absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
		);
	const manifest: unknown = JSON.parse(input.packageManifest.source);
	if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
		throw new Error('Angular migration: the package manifest is not a JSON object');
	const aligned = alignAngularPackageManifest(
		manifest as Readonly<Record<string, unknown>>,
		cell,
		workspace.removedPackages,
	);
	unhandled.push(...aligned.unhandled);
	declaredDifferences.push(...aligned.declaredDifferences);
	/**
	 * Holes the closure carries are closed after the cell alignment, not before:
	 * the cell decides which lines the workspace runs, and an undeclared edge is
	 * declared at the line the cell read for it.
	 */
	const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
	const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
	unhandled.push(...declared.unhandled);
	declaredDifferences.push(...declared.declaredDifferences);
	/**
	 * The holes the *application's own source* carries are closed after the cell
	 * alignment for a second reason: the alignment is what drops the packages the
	 * cell found no successor for, and a package the application imports directly
	 * that the era closure supplied through one of those is only visible as a hole
	 * once the wrapper is gone. Reading it before the disposition would report the
	 * edge as satisfied and leave the migrated tree unable to resolve it.
	 */
	const applicationDependencies = declareApplicationSourceDependencies(
		declared.manifest,
		readApplicationPackageUses(input.sourceModules),
		cell,
		input.eraClosureTypePackages ?? [],
	);
	unhandled.push(...applicationDependencies.unhandled);
	declaredDifferences.push(...applicationDependencies.declaredDifferences);
	/**
	 * The packages the migrated workspace's own targets name are declared last,
	 * after every capability that decides which targets survive: a builder
	 * declaration for a target the workspace migration removed would install a
	 * toolchain nothing runs.
	 */
	const builders = declareBuilderPackages(
		applicationDependencies.manifest,
		workspace.config,
		cell,
	);
	unhandled.push(...builders.unhandled);
	/**
	 * The workspace's own runtime declaration is retargeted after every
	 * capability that decides what the closure is: `engines.node` is a statement
	 * about the cell the manifest now installs for, so it is written once the
	 * manifest has finished becoming that cell's manifest. It stands down on a
	 * workspace that declares no engines, and on one whose declaration already
	 * admits the cell's Node line.
	 */
	const engines = retargetWorkspaceEngines(builders.manifest, cell);
	unhandled.push(...engines.unhandled);
	declaredDifferences.push(...engines.declaredDifferences);
	const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
	unhandled.push(...tsConfig.unhandled);
	const files: MigratedFile[] = [
		file(
			input.packageManifest,
			`${JSON.stringify(engines.manifest, null, 2)}\n`,
			'workspace',
			[
				...aligned.changes.map(describeDependencyChange),
				...declared.declarations.map(
					(entry) =>
						`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
				),
				...applicationDependencies.declarations.map(
					(entry) =>
						`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
				),
				...builders.declarations.map(
					(entry) =>
						`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
				),
				...(engines.retarget === null
					? []
					: [
							`retargeted ${engines.retarget.field} from ${engines.retarget.from} to ` +
								`${engines.retarget.to} — ${engines.retarget.reason}`,
						]),
			],
		),
		file(
			synthesis === null
				? input.workspaceConfig
				: { path: synthesis.path, source: input.workspaceConfig.source },
			workspace.config,
			'workspace',
			synthesis === null
				? workspace.changes.map(describeConfigChange)
				: [
						`synthesized ${synthesis.path} from ${synthesis.replacedPath}, the pre-angular.json ` +
							'Angular CLI 1.x workspace format; the digest recorded before is that file',
						...synthesis.changes.map(describeConfigChange),
						...workspace.changes.map(describeConfigChange),
					],
		),
		file(
			input.tsConfig,
			tsConfig.config,
			'workspace',
			tsConfig.changes.map(describeConfigChange),
		),
	];
	/**
	 * Source capabilities run in sequence over each module, each one handed what
	 * the last produced. They are independent — one rewrites module specifiers,
	 * the next replaces a removed NgRx decorator — and a module is counted as
	 * changed if any of them changed a byte of it.
	 */
	/**
	 * One capability is not per-module and cannot be: rewriting a modal call site
	 * without rewriting the content component it supplied is the silent failure
	 * that capability exists to refuse. It runs over the whole tree first, and
	 * what it produced is what the per-module capabilities then see.
	 */
	const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
	unhandled.push(...modal.unhandled);
	const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
	const baseClassDiagnostics = new Map(
		(input.baseClassDiagnostics ?? []).map((entry) => [entry.path, entry.diagnostics]),
	);
	const missingMembers = new Map(
		(input.missingMemberDiagnostics ?? []).map((entry) => [entry.path, entry.diagnostics]),
	);
	for (const module of [...input.sourceModules].sort((left, right) =>
		compareStrings(left.path, right.path),
	)) {
		const modalFile = modalByPath.get(module.path);
		const entrySource = modalFile?.source ?? module.source;
		/**
		 * The compiler-positioned capability runs first of the per-module
		 * capabilities, because its input is a pair of coordinates into bytes the
		 * caller compiled and every capability that edits the module moves them. It
		 * is safe wherever it is placed — it refuses a position where the name it was
		 * told to fill is not written — but placed first it is refused least often
		 * for a reason that is about ordering rather than about the application.
		 */
		const baseClasses = parameteriseBaseClasses(
			module.path,
			entrySource,
			baseClassDiagnostics.get(module.path) ?? [],
			input.genericBaseClasses ?? [],
		);
		/**
		 * The second compiler-positioned capability runs beside the first and for
		 * the same reason: a `TS2339` position is a position in the bytes the caller
		 * compiled, and the base-class parameterisation above only ever writes inside
		 * an `extends` clause's type arguments — so a position it moved is a position
		 * on the same line, and this capability re-checks the member is written where
		 * it was told before it edits anything.
		 */
		const departedDomMembers = accommodateDepartedDomMembers(
			module.path,
			baseClasses.source,
			missingMembers.get(module.path) ?? [],
		);
		const migrated = migrateAngularSourceModule(module.path, departedDomMembers.source);
		const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
		const sentry = migrateSentryV8Tracing(module.path, effects.source);
		/**
		 * Deep imports are redirected after the specifier rewrites and before the
		 * capabilities that read module literals: an unreachable subpath is a
		 * question about the specifier, and the answer changes which declaration each
		 * symbol arrives on. Every reading the caller supplied is offered the module
		 * in turn, because two packages are two exports maps.
		 */
		let deepImportSource = sentry.source;
		const deepImportChanges: DeepImportChange[] = [];
		for (const reading of input.deepImportReadings ?? []) {
			const redirected = redirectUnreachableImports(module.path, deepImportSource, reading);
			unhandled.push(...redirected.unhandled);
			deepImportChanges.push(...redirected.changes);
			deepImportSource = redirected.source;
		}
		/**
		 * `entryComponents` is dropped last of the per-module capabilities, and the
		 * order is not arbitrary: the capability proves, per literal, that every
		 * component the property names is still reached by `declarations` or
		 * `bootstrap` of the same literal, and it should see the literal as the
		 * capabilities before it left it rather than as the era file wrote it.
		 */
		const entryComponents = removeEntryComponents(module.path, deepImportSource);
		/**
		 * Three type-position insertions close the sequence. Each one is a claim
		 * about a type the source itself already states — the module a static factory
		 * is declared on, and the `void` a subject or a promise executor proves by
		 * settling with nothing — so each gates on its own construct and inserts
		 * nothing where it cannot read one. They are placed after the specifier
		 * rewrites because the bindings they resolve are the bindings those rewrites
		 * left, and before nothing: no later capability reads a module.
		 */
		const moduleWithProviders = addModuleWithProvidersTypeArgument(
			module.path,
			entryComponents.source,
		);
		const voidSubjects = parameteriseVoidSubjects(module.path, moduleWithProviders.source);
		const voidExecutors = parameteriseVoidPromiseExecutors(module.path, voidSubjects.source);
		/**
		 * The decorator synthesis closes the sequence. It inserts a line above a class
		 * declaration and a name into an import declaration, which moves every offset
		 * below both — so it runs after every capability positioned by an offset, and
		 * it reads its own precondition out of the module the others left.
		 */
		const undecorated = decorateUndecoratedBaseClasses(
			module.path,
			voidExecutors.source,
			cell,
		);
		unhandled.push(
			...departedDomMembers.unhandled,
			...undecorated.unhandled,
			...baseClasses.unhandled,
			...migrated.unhandled,
			...effects.unhandled,
			...sentry.unhandled,
			...entryComponents.unhandled,
			...moduleWithProviders.unhandled,
			...voidSubjects.unhandled,
			...voidExecutors.unhandled,
		);
		files.push(
			file(module, undecorated.source, 'application', [
				...(modalFile?.changes ?? []).map(describeSourceChange),
				...baseClasses.changes.map(describeBaseClassChange),
				...departedDomMembers.changes.map(describeDepartedDomMemberChange),
				...deepImportChanges.map(describeDeepImportChange),
				...undecorated.changes.map(describeUndecoratedBaseClassChange),
				...migrated.changes.map(describeSourceChange),
				...effects.changes.map(describeSourceChange),
				...sentry.changes.map(describeSourceChange),
				...entryComponents.changes.map(describeEntryComponentsChange),
				...moduleWithProviders.changes.map(describeModuleWithProvidersChange),
				...voidSubjects.changes.map(describeVoidSubjectChange),
				...voidExecutors.changes.map(describeVoidExecutorChange),
			]),
		);
	}
	/**
	 * Templates are the last application capability, and it is cross-file by
	 * nature: whether a call site's binding order is safe is a question about the
	 * directive the element resolves to, read from that directive's own class.
	 * The readings are taken from the modules as the per-module capabilities left
	 * them, so a directive whose imports those capabilities rewrote still
	 * resolves. A template no directive reading touches is carried through
	 * unchanged and still counted, so the scanned total means what it says.
	 */
	const directiveReadings: DirectiveBindingReading[] = [];
	for (const entry of files)
		if (entry.kind === 'application' && entry.path.endsWith('.ts'))
			directiveReadings.push(...readDirectiveBindingDependencies(entry.path, entry.source));
	for (const template of [...(input.templates ?? [])].sort((left, right) =>
		compareStrings(left.path, right.path),
	)) {
		const reordered = reorderTemplateBindings(template.path, template.source, directiveReadings);
		unhandled.push(...reordered.unhandled);
		files.push(
			file(
				template,
				reordered.source,
				'application',
				reordered.changes.map(describeBindingReorderChange),
			),
		);
	}
	/**
	 * Stylesheets are application files too, and a blocked package subpath is an
	 * application file that no longer builds. Each is offered to every package
	 * reading the caller supplied; a stylesheet no reading touches is carried
	 * through unchanged and still counted, so the scanned total means what it says.
	 */
	for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
		compareStrings(left.path, right.path),
	)) {
		let source = sheet.source;
		const changes: string[] = [];
		for (const reading of input.packageExports ?? []) {
			const styles = migratePackageStyleImports(sheet.path, source, reading);
			unhandled.push(...styles.unhandled);
			declaredDifferences.push(...styles.declaredDifferences);
			changes.push(...styles.changes.map(describeSourceChange));
			source = styles.source;
		}
		files.push(file(sheet, source, 'application', changes));
	}
	const applicationFiles = files.filter((entry) => entry.kind === 'application');
	return Object.freeze({
		cell: cell.id,
		files: Object.freeze(files),
		applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
		workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
			.length,
		applicationFilesScanned: applicationFiles.length,
		unhandled: Object.freeze([...new Set(unhandled)]),
		declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
		removedFiles: Object.freeze([
			...configRemovals.map((removal) => removal.at),
			...(synthesis === null ? [] : [synthesis.replacedPath]),
		]),
	});
}

